def split_csv(line):
    fields = []
    i = 0

    while i <= len(line):
        # Parse one field
        if i == len(line):
            # End of line - add empty field if we're at a position after a comma
            if fields or i > 0:
                fields.append('')
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = ''
            while i < len(line):
                if line[i] == '"':
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows: comma or end of line
                        if i < len(line):
                            if line[i] != ',':
                                return None
                            i += 1  # Skip the comma
                        fields.append(field)
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line while in quoted field
                return None
        else:
            # Unquoted field
            field = ''
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field cannot contain quotes
                    return None
                field += line[i]
                i += 1

            fields.append(field)
            if i < len(line):
                i += 1  # Skip the comma

    return fields if fields else ['']

